  async Task LoadDiscovery(){if(discoveryLoading||cancel.IsCancellationRequested)return;discoveryLoading=true;discoveryStatus.Text="Loading current PC deals…";discoveryGrid.Children.Clear();try{string term=discoverySearch.Text;var deals=await GameDiscoveryCatalog.GetDealsAsync(term,cancel.Token);var catalog=new List<DiscoveryGame>();var credentials=GameDiscoveryCatalog.GetIgdbCredentials();if(credentials!=null){try{string token=await GameDiscoveryCatalog.GetIgdbTokenAsync(credentials.Item1,credentials.Item2,cancel.Token);catalog=await GameDiscoveryCatalog.GetCatalogAsync(credentials.Item1,token,term,cancel.Token);}catch(OperationCanceledException){throw;}catch{discoveryStatus.Text="IGDB could not connect. Showing current CheapShark deals; check the saved Twitch credentials and retry.";}}
    foreach(var deal in deals){var match=catalog.FirstOrDefault(x=>NormalizeTitle(x.Name)==NormalizeTitle(deal.Name));if(match!=null){deal.Summary=match.Summary;deal.Genres=match.Genres;deal.Platforms=match.Platforms;deal.ReleaseDate=match.ReleaseDate;if(!string.IsNullOrWhiteSpace(match.CoverUrl))deal.CoverUrl=match.CoverUrl;if(match.Rating.HasValue){deal.Rating=match.Rating;deal.RatingSource=match.RatingSource;}}}
    var shown=deals.Cast<DiscoveryGame>().ToList();if(catalog.Count>0){var matched=new HashSet<string>(deals.Select(x=>NormalizeTitle(x.Name)));shown.AddRange(catalog.Where(x=>!matched.Contains(NormalizeTitle(x.Name))).Take(12));}foreach(var item in shown)discoveryGrid.Children.Add(DiscoveryCard(item));discoveryStatus.Text=deals.Count+" current PC deals from CheapShark"+(catalog.Count>0?" · IGDB catalog connected":credentials==null?" · Add IGDB credentials for descriptions, genres, ratings, and platform details":" · IGDB unavailable; deals are still shown");if(shown.Count==0)discoveryGrid.Children.Add(new TextBlock{Text="No matching games found. Try a shorter title.",Foreground=Muted,Margin=new Thickness(10)});discoveryLoaded=true;
   }catch(OperationCanceledException){}catch(Exception ex){discoveryLoaded=false;discoveryStatus.Text="Game discovery could not load: "+ex.GetBaseException().Message+". Check your connection, or try again later.";}finally{discoveryLoading=false;}}
  string NormalizeTitle(string value){return new string((value??"").ToLowerInvariant().Where(char.IsLetterOrDigit).ToArray());}
