f":""),Foreground=Good,FontSize=13,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,7,0,0)};body.Children.Add(price);var deal=MakeButton("View deal at "+(game.StoreName??"store"));deal.HorizontalAlignment=HorizontalAlignment.Left;deal.Margin=new Thickness(0,6,0,0);deal.Click+=delegate{if(!string.IsNullOrWhiteSpace(game.DealUrl))try{System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo(game.DealUrl){UseShellExecute=true});}catch{}};body.Children.Add(deal);}else body.Children.Add(new TextBlock{Text=game.Platforms??"PC game",Foreground=Accent,FontSize=11,Margin=new Thickness(0,6,0,0)});stack.Children.Add(body);card.Child=stack;return card;}
